-- Restrict "any signed-in user" policies to internal team members (users with a role).
ALTER POLICY "auth_read_log" ON public.agent_activity_log USING (public.is_internal_user(auth.uid()));
ALTER POLICY "auth_read_status" ON public.agent_status USING (public.is_internal_user(auth.uid()));
ALTER POLICY "auth_read_agents" ON public.ai_agents USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated can read app_roles" ON public.app_roles USING (public.is_internal_user(auth.uid()));
ALTER POLICY "auth_read_queue" ON public.ceo_approval_queue USING (public.is_internal_user(auth.uid()));
ALTER POLICY "auth read fse_drive_index" ON public.fse_drive_index USING (public.is_internal_user(auth.uid()));
ALTER POLICY "authenticated read flags" ON public.fse_supplier_flags USING (public.is_internal_user(auth.uid()));
ALTER POLICY "authenticated update flags" ON public.fse_supplier_flags USING (public.is_internal_user(auth.uid())) WITH CHECK (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated can read fse sync state" ON public.fse_sync_state USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated users can manage item_notes" ON public.item_notes USING (public.is_internal_user(auth.uid())) WITH CHECK (public.is_internal_user(auth.uid()));
ALTER POLICY "ops_actions_auth_all" ON public.ops_actions USING (public.is_internal_user(auth.uid())) WITH CHECK (public.is_internal_user(auth.uid()));
