ALTER POLICY "Authenticated can view partners" ON public.partners USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated can read permissions" ON public.permissions USING (public.is_internal_user(auth.uid()));
ALTER POLICY "votes readable by team" ON public.platform_feedback_votes USING (public.is_internal_user(auth.uid()));
ALTER POLICY "auth_read_product_types" ON public.product_types USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated can view products" ON public.products USING (public.is_internal_user(auth.uid()));
