ALTER POLICY "Authenticated can view supplier scores" ON public.supplier_scores USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated can view services" ON public.supplier_services USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated can view suppliers" ON public.suppliers USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated users can view settings" ON public.system_settings USING (public.is_internal_user(auth.uid()));
ALTER POLICY "Authenticated can manage itineraries" ON public.itineraries USING (public.is_internal_user(auth.uid())) WITH CHECK (public.is_internal_user(auth.uid()));
